(3476, 99, 'Si una fórmula crea una referencia circular intencional (por ejemplo, para un modelo iterativo), ¿qué ajuste permite que Excel la calcule?', NULL, '1.00'),
(3477, 99, '¿Cuál es la causa más común del error #¡DERRAME! (#SPILL!) en Excel 365?', NULL, '1.00'),
(3478, 99, '¿Qué hace la función TOMAR (TAKE) aplicada a una matriz derramada, por ejemplo =TOMAR(A1#;5)?', NULL, '1.00');
